/* Object animation controls and smooth editable freehand strokes. */
(function(){'use strict';const FX=M.sceneFX;let brushColor='#354747',brushSize=7,stroke=null;
const titles={'none':'None','shake':'Shake','rotate':'Rotate','float':'Float','pulse':'Pulse','bounce':'Bounce','swing':'Swing','fade':'Fade','pop':'Pop up','slide-left':'Slide left','slide-right':'Slide right','slide-up':'Slide up','slide-down':'Slide down','spin':'Spin in','shrink':'Shrink','glow':'Glow','discovery':'Discovery / realization','snore':'Snoring Zzz','ring':'Ringing waves','bad-smell':'Bad smell','dark-aura':'Dark aura','spotlight':'Spotlight / dark surroundings','lamp-light':'Lamp light / dark room'};
const selector=(key,label,choices,value)=>`<label class="field">${label}<select data-animation="${key}">${choices.map(v=>`<option value="${v}" ${v===value?'selected':''}>${titles[v]||v.replaceAll('-',' ')}</option>`).join('')}</select></label>`;
const beforeInspector=renderInspector;renderInspector=function(){beforeInspector();const host=$('#inspectorContent');if(tool==='freehand'){host.insertAdjacentHTML('afterbegin',`<section><h3>Freehand pen</h3><label class="field">Ink color<input id="penColor" type="color" value="${brushColor}"></label><label class="field">Brush size<input id="penSize" type="range" min="1" max="60" value="${brushSize}"></label><p class="note">Draw directly on this frame. Each stroke can be moved, resized, grouped or deleted. Ctrl + Z undoes a stroke.</p><button id="finishDrawing" class="wide">Done drawing</button></section>`);$('#penColor').oninput=e=>brushColor=e.target.value;$('#penSize').oninput=e=>brushSize=Number(e.target.value);$('#finishDrawing').onclick=()=>{setTool('select');renderInspector()}}const o=current();if(!o)return;const a=FX.settings(o);host.insertAdjacentHTML('beforeend',`<section><h3>Object animation</h3>${selector('motion','Repeating motion',FX.motions,a.motion)}${selector('entry','Entrance',FX.entries,a.entry)}${selector('exit','Exit',FX.exits,a.exit)}${[['speed','Motion speed',a.speed,.1,5,.1],['amount','Motion amount',a.amount,0,150,1],['duration','Entrance / exit seconds',a.duration,.04,10,.01],['delay','Entrance delay',a.delay,0,frame().duration,.01]].map(([k,label,v,min,max,step])=>`<label class="field">${label}<input data-animation="${k}" type="number" value="${v}" min="${min}" max="${max}" step="${step}"></label>`).join('')}<button id="previewObjectMotion" class="wide">▶ Preview this frame</button><p class="note">Timing restarts on each frame. Presets combine with motion paths.</p></section><section><h3>Visual effects</h3><div class="effect-choices">${FX.effects.map(v=>`<label><input type="checkbox" data-effect="${v}" ${(o.effects||[]).includes(v)?'checked':''}> ${titles[v]||v.replaceAll('-',' ')}</label>`).join('')}</div><label class="field">Effect color<input data-fx="effectColor" type="color" value="${o.effectColor||'#ffdb83'}"></label><label class="field">Intensity<input data-fx="effectStrength" type="range" min="0" max="1" step=".05" value="${o.effectStrength??.65}"></label><label class="field">Effect size<input data-fx="effectSize" type="range" min=".3" max="4" step=".1" value="${o.effectSize||1}"></label><p class="note">Snoring and ringing here are visual effects. Add their sounds on the audio timeline.</p></section>`);$$('[data-animation]').forEach(input=>input.onchange=()=>{remember();for(const object of selectedObjects()){object.animation??={};object.animation[input.dataset.animation]=input.tagName==='SELECT'?input.value:Math.max(+input.min,Math.min(+input.max,Number(input.value)||0))}changed()});$$('[data-effect]').forEach(input=>input.onchange=()=>{remember();for(const object of selectedObjects()){const list=new Set(object.effects||[]);input.checked?list.add(input.dataset.effect):list.delete(input.dataset.effect);object.effects=[...list]}changed()});$$('[data-fx]').forEach(input=>input.onchange=()=>{remember();selectedObjects().forEach(o=>o[input.dataset.fx]=input.type==='color'?input.value:Number(input.value));changed()});$('#previewObjectMotion').onclick=()=>{const ids=[...selected];AudioTimeline.seek(startTime());selected=ids;renderInspector();play()};};
const button=document.createElement('button');button.dataset.tool='freehand';button.title='Freehand drawing (B)';button.textContent='✎';$('#tools').append(button);button.onclick=()=>setTool('freehand');const oldTool=setTool;setTool=function(t){oldTool(t);if(t==='freehand'){$('#hint').textContent='Draw smoothly on the frame · change ink and brush size in Properties';stage.style.cursor='crosshair'}else stage.style.cursor='';renderInspector()};document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='b'&&!e.ctrlKey&&!e.metaKey&&!$('#modal').open&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))setTool('freehand')});
function updateStroke(){const points=stroke.points,pad=stroke.o.brushWidth/2+1,x=Math.min(...points.map(p=>p.x))-pad,y=Math.min(...points.map(p=>p.y))-pad,w=Math.max(...points.map(p=>p.x))-x+pad,h=Math.max(...points.map(p=>p.y))-y+pad;Object.assign(stroke.o,{x:x+w/2,y:y+h/2,w,h,inkWidth:w,inkHeight:h,points:points.map(p=>({x:p.x-x,y:p.y-y}))});draw()}
const down=stage.onpointerdown,move=stage.onpointermove,up=stage.onpointerup,cancel=stage.onpointercancel;
stage.onpointerdown=e=>{if(tool!=='freehand')return down(e);if(e.button!==0||exporting)return;e.preventDefault();stop();AudioTimeline.beginEdit();remember();stage.setPointerCapture(e.pointerId);const p=worldPoint(e),o=M.make('freehand',p.x,p.y);o.name='Freehand stroke';o.fill=brushColor;o.brushWidth=brushSize;o.points=[];o.inkWidth=1;o.inkHeight=1;frame().objects.push(o);selected=[o.id];stroke={o,points:[p],pointer:e.pointerId};updateStroke()};
stage.onpointermove=e=>{if(!stroke)return move(e);if(e.pointerId!==stroke.pointer)return;for(const event of e.getCoalescedEvents?.().length?e.getCoalescedEvents():[e]){const p=worldPoint(event),last=stroke.points.at(-1);if(Math.hypot(p.x-last.x,p.y-last.y)>.6&&stroke.points.length<12000)stroke.points.push(p)}updateStroke()};
function finish(e){if(!stroke)return false;if(e?.pointerId!==undefined&&e.pointerId!==stroke.pointer)return false;if(Number.isFinite(e?.clientX)&&Number.isFinite(e?.clientY)){const p=worldPoint(e),last=stroke.points.at(-1);if(Math.hypot(p.x-last.x,p.y-last.y)>.6&&stroke.points.length<12000)stroke.points.push(p)}updateStroke();stroke=null;changed();return true}
stage.onpointerup=e=>{if(!finish(e))up(e)};stage.onpointercancel=e=>{if(!finish(e))cancel?.(e)};
const priorValidate=validateProject;validateProject=p=>{p=priorValidate(p);let total=0;function check(o){if(o.type==='freehand'){if(!Array.isArray(o.points)||!o.points.length||o.points.length>12000||o.points.some(q=>!Number.isFinite(q.x)||!Number.isFinite(q.y))||!Number.isFinite(o.inkWidth)||!Number.isFinite(o.inkHeight)||o.inkWidth<=0||o.inkHeight<=0||!Number.isFinite(o.brushWidth)||o.brushWidth<=0)throw Error('Invalid freehand drawing.');total+=o.points.length;if(total>1000000)throw Error('Too many drawing points in this project.')}if(o.animation)o.animation=FX.settings(o);if(o.effects)o.effects=Array.isArray(o.effects)?o.effects.filter(v=>FX.effects.includes(v)):[];for(const child of o.children||[])check(child)}p.frames.forEach(f=>f.objects.forEach(check));Object.values(p.customObjects||{}).forEach(check);return p};window.SceneTools={getBrush:()=>({color:brushColor,size:brushSize})};
})();
